  ('a3b04ab9-5e4d-5f92-9908-9488ccc46211', null, (select id from public.skills where slug = 'write-g10-paragraph-transitions'), null, 'easy',
   $q$Read: "The new footbridge was designed to sway slightly in strong winds. ____, the engineers told the city that walkers might feel some movement on gusty days." Which transition best completes the sentences?$q$, $q$[{"text":"For example,","is_correct":false,"misconception_token":"example-for-effect"},{"text":"Accordingly,","is_correct":true},{"text":"In contrast,","is_correct":false,"misconception_token":"contrast-for-effect"},{"text":"Nevertheless,","is_correct":false,"misconception_token":"contrast-for-effect"}]$q$::jsonb, $q$Accordingly,$q$, $q$The engineers' warning follows directly from the bridge's design, so "Accordingly" shows the result. "Nevertheless" is wrong because the warning matches the design instead of going against it.$q$, 'draft', null)
